import type { ReviewInput } from '../types/review';

// Live demo input. Findings are generated by the backend, not prefilled here.
export const demoSnippet: ReviewInput = {
  title: 'Build a checkout quote',
  language: 'typescript',
  context: [
    'This endpoint builds a USD checkout quote; it does not place an order or charge a payment.',
    'Cart items and couponCode come from a request. Upstream validation checks only that SKUs are nonempty strings and quantities are positive integers.',
    'Catalog SKUs are lowercase. Repeated SKUs are allowed and their quantities must be added together.',
    'db.query returns an array of product rows with sku and price_cents; prices and all quote amounts are integer cents.',
    'promotions.findActive returns null or an active promotion whose percentOff is a whole percentage from 0 to 100 (15 means 15%, not 0.15).',
    'Shipping is a flat 500 cents after the merchandise discount; tax is handled elsewhere.',
    'Example: mug costs 2500 cents, cart items are [{sku:"mug",quantity:1},{sku:"mug",quantity:2}], and SAVE15 has percentOff:15.',
    'The expected quote has one mug line with quantity 3, subtotal 7500, discount 1125, shipping 500, and total 6875 cents.',
  ].join(' '),
  code: [
    "import { db } from './database';",
    "import { promotions } from './promotions';",
    '',
    'type Product = { sku: string; price_cents: number };',
    'type QuoteRequest = {',
    '  items: { sku: string; quantity: number }[];',
    '  couponCode?: string;',
    '};',
    '',
    'export async function buildQuote(request: QuoteRequest) {',
    '  if (request.items.length === 0) {',
    "    return { status: 400, message: 'Cart is empty' };",
    '  }',
    '',
    '  const normalizedItems = request.items.map((item) => ({',
    '    sku: item.sku.trim().toLowerCase(),',
    '    quantity: item.quantity,',
    '  }));',
    "  const quotedSkus = normalizedItems.map((item) => `'${item.sku}'`);",
    "  const skuList = quotedSkus.join(', ');",
    '  const lookupSql = `SELECT sku, price_cents FROM products WHERE sku IN (${skuList})`;',
    '  const products: Product[] = await db.query(lookupSql);',
    '  const catalogBySku = new Map(products.map((product) => [product.sku, product]));',
    '',
    '  const missingItem = normalizedItems.find((item) => !catalogBySku.has(item.sku));',
    '  if (missingItem) {',
    "    return { status: 404, message: 'Product not found' };",
    '  }',
    '',
    '  const quantitiesBySku = new Map(',
    '    normalizedItems.map((item) => [item.sku, item.quantity]),',
    '  );',
    '  const uniqueSkus = [...new Set(normalizedItems.map((item) => item.sku))];',
    '  const lines = uniqueSkus.map((sku) => {',
    '    const product = catalogBySku.get(sku)!;',
    '    const quantity = quantitiesBySku.get(sku)!;',
    '    const unitPriceCents = product.price_cents;',
    '    const lineTotalCents = unitPriceCents * quantity;',
    '    return { sku, quantity, unitPriceCents, lineTotalCents };',
    '  });',
    '',
    '  const subtotalCents = lines.reduce((sum, line) => sum + line.lineTotalCents, 0);',
    '  const promotion = request.couponCode',
    '    ? await promotions.findActive(request.couponCode)',
    '    : null;',
    '  const discountRate = promotion?.percentOff ?? 0;',
    '  const discountCents = Math.round(subtotalCents * discountRate);',
    '  const discountedSubtotalCents = Math.max(0, subtotalCents - discountCents);',
    '  const shippingCents = 500;',
    '  const totalCents = discountedSubtotalCents + shippingCents;',
    '',
    '  return {',
    '    status: 200, lines, subtotalCents, discountCents, shippingCents, totalCents,',
    '  };',
    '}',
  ].join('\n'),
};
